/**
 * Two manifest corrections that only matter once the app is on Google Play.
 *
 * `android/` is regenerated by `expo prebuild` on every build, so a hand edit to the
 * manifest is destroyed before it is ever compiled. This is the supported way to make
 * one stick, and it needs no new dependency: `expo/config-plugins` already ships
 * inside the `expo` package.
 *
 * 1. CAMERA AND RECORD_AUDIO SILENTLY REQUIRE HARDWARE. Android's rule is that
 *    declaring either permission implies `<uses-feature required="true">` for the
 *    matching hardware unless the manifest says otherwise, and Play uses that to
 *    decide which devices may install the app. Left alone, every Chromebook and every
 *    tablet without a microphone is filtered out of the listing — and the one tool
 *    that uses this hardware, the Match Tracker, is optional, not the app. The app's
 *    actual job, a team messaging and scheduling, needs neither.
 *
 *    `camera.autofocus` is listed separately because CAMERA implies that one too.
 *
 * 2. SYSTEM_ALERT_WINDOW SHIPS FROM THE TEMPLATE AND IS NOT USED. "Draw over other
 *    apps" is one of the permissions Play asks a developer to justify, and this app
 *    has no floating window to draw. React Native wants it for the development
 *    overlay, which is why `android/app/src/debug/AndroidManifest.xml` declares it as
 *    well — that copy is untouched, so `npx expo run:android` keeps its dev menu.
 *
 * Both are asserted in `.github/workflows/android-apk.yml` after prebuild, because a
 * config plugin that silently stops matching the template is exactly the kind of
 * failure that ships.
 */
const { withAndroidManifest } = require('expo/config-plugins');

/** Hardware this app can do without. */
const OPTIONAL_FEATURES = [
  'android.hardware.camera',
  'android.hardware.camera.autofocus',
  'android.hardware.microphone',
];

const DROP_PERMISSIONS = ['android.permission.SYSTEM_ALERT_WINDOW'];

module.exports = function withPlayManifest(config) {
  return withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults.manifest;

    manifest['uses-permission'] = (manifest['uses-permission'] ?? []).filter(
      (p) => !DROP_PERMISSIONS.includes(p.$?.['android:name']),
    );

    const features = (manifest['uses-feature'] ??= []);
    for (const name of OPTIONAL_FEATURES) {
      const existing = features.find((f) => f.$?.['android:name'] === name);
      if (existing) existing.$['android:required'] = 'false';
      else features.push({ $: { 'android:name': name, 'android:required': 'false' } });
    }

    return cfg;
  });
};
